class CountingStore:
    def __init__(self, inner):
        self._inner = inner
        self.count = 0

    def __getattr__(self, name):                 # everything not defined here
        return getattr(self._inner, name)        # is forwarded to the delegate

    def save(self, id):                          # explicit override, forward inside
        self.count += 1
        return self._inner.save(id)
